{"command": "cd /root && python3 << 'EOF'
import fitz, re
# More thorough URL / username search across all 3 papers (before references)
refs = {"paper1.pdf": 9, "paper2.pdf": 4, "paper3.pdf": 4}
pat = re.compile(r"(https?://[^\s)]+|github\.com/[\w.-]+|huggingface\.co/[\w./-]+)")
for p, r in refs.items():
    d = fitz.open(p)
    found = set()
    for i in range(r):
        t = d[i].get_text()
        for m in pat.findall(t):
            found.add(m)
    print(p, "URLs before refs:")
    for u in sorted(found):
        print("  ", u)
    d.close()
EOF
", "security_risk": "LOW", "summary": "Enumerate URLs in body of each paper"}

